import numpy as np

def project(X, u):
    X = np.asarray(X, dtype=float)
    u = np.asarray(u, dtype=float)
    uu = u @ u
    if uu == 0:
        return np.zeros_like(X), X.copy()
    coef = X @ u / uu                  # (n,): scalar coordinate of each row along u
    P = coef[:, None] * u              # (n, 1) * (d,) -> (n, d)
    return P, X - P
